-- Factory is pg_temp and only used inside this rolled-back privileged test transaction.
create function pg_temp.media_fixture(asset uuid, owner_uid uuid, purpose_arg text) returns void language plpgsql as $$
declare attempt uuid:=gen_random_uuid(); manifest jsonb:='{}'; v text;
begin
 foreach v in array array['thumb','card','full'] loop
  manifest:=manifest||jsonb_build_object(v,jsonb_build_object('key','processed/'||asset||'/'||attempt||'/'||v||'.webp','sha256',repeat('a',64),'bytes',100));
 end loop;
 insert into public.media_assets(id,owner_id,purpose,status,private_storage_path,input_mime_type,byte_size,width_px,height_px,exif_stripped,ready_attempt_id,ready_manifest,content_sha256)
 values(asset,owner_uid,purpose_arg,'ready','raw/'||asset,'image/jpeg',100,400,400,true,attempt,manifest,repeat('a',64));
end $$;
