-- FORCE RLS must also constrain a nonsuperuser table owner.
create role padelhub_test_owner nologin nobypassrls;
grant padelhub_test_owner to postgres;
grant usage,create on schema public to padelhub_test_owner;
grant usage on schema extensions to padelhub_test_owner;
